// FUNCTION: BFME2 0x0053E17E size=312 name=?updateOCLTimerTextDisplay@ControlBar@@IAEXIM@Z evidence=N:ledger

void ControlBar::updateOCLTimerTextDisplay(unsigned int totalSeconds, float percent)
{
	UnicodeString text;
	static NameKeyType descriptionID = TheNameKeyGenerator->nameToKey("ControlBar.wnd:OCLTimerStaticText");
	GameWindow *descWindow = TheWindowManager->winGetWindowFromId(0, descriptionID);
	static NameKeyType barID = TheNameKeyGenerator->nameToKey("ControlBar.wnd:OCLTimerProgressBar");
	GameWindow *barWindow = TheWindowManager->winGetWindowFromId(0, barID);
	int minutes = totalSeconds / 60;
	int seconds = totalSeconds - minutes * 60;
	if (seconds < 10)
		text.format(TheGameText->fetchPtr("CONTROLBAR:OCLTimerDescWithPadding"), minutes, seconds);
	else
		text.format(TheGameText->fetchPtr("CONTROLBAR:OCLTimerDesc"), minutes, seconds);
	GadgetStaticTextSetText(descWindow, text);
	GadgetProgressBarSetProgress(barWindow, (int)(percent * 100.0f));
	m_displayedOCLTimerSeconds = totalSeconds;
}

// FUNCTION: BFME2 0x0053E2B6 size=148 name=?updateContextOCLTimer@ControlBar@@IAEXXZ evidence=N:ledger
void ControlBar::updateContextOCLTimer()
{
	Object *obj = m_currentSelectedDrawable->getObject();
	if (!obj)
		return;
	static const NameKeyType key_OCLUpdate = TheNameKeyGenerator->nameToKey("OCLUpdate");
	OCLUpdate *update = (OCLUpdate *)obj->findUpdateModule(key_OCLUpdate);
	unsigned int frames = update->getRemainingFrames();
	unsigned int seconds = frames / BfmeLogicFramesPerSecond;
	float percent = update->getCountdownPercent();
	if (m_displayedOCLTimerSeconds != seconds)
		updateOCLTimerTextDisplay(seconds, percent);
}

// FUNCTION: BFME2 0x0053E34A size=156 name=?populateOCLTimer@ControlBar@@QAEXPAVObject@@@Z evidence=N:ledger
void ControlBar::populateOCLTimer(Object *creatorObject)
{
	if (creatorObject == 0)
		return;
	GameWindow *parent = m_contextParent[7];
	const CommandButton *button;
	{
		AsciiString name("Command_Sell");
		button = findCommandButton(name);
	}
	NameKeyType key = TheNameKeyGenerator->nameToKey(
		"ControlBar.wnd:OCLTimerSellButton");
	GameWindow *sellButton = TheWindowManager->winGetWindowFromId(parent, key);
	setControlCommand(sellButton, button);
	sellButton->winSetStatus(0x00200000);
	updateContextOCLTimer();
	setPortraitByObject(creatorObject);
}

